toolScript:
const baseColors = [
            { hex: '#ffffff', name: 'White' },
            { hex: '#000000', name: 'Black' },
            { hex: '#ff0000', name: 'Red' },
            { hex: '#00ff00', name: 'Green' },
            { hex: '#0000ff', name: 'Blue' },
            { hex: '#ffff00', name: 'Yellow' },
            { hex: '#00ffff', name: 'Cyan' },
            { hex: '#ff00ff', name: 'Magenta' }
        ];
        let colors = [...baseColors];
        let currentIndex = 0;
        let hudTimeout;
        let colorsViewed = new Set();
        let fixerInterval;
        function startTest(index, colorHex) {
            const layer = document.getElementById('diagnostic-layer');
            colorsViewed.clear();
            // Set initial color
            if (colorHex) {
                const foundIdx = colors.findIndex(c => c.hex === colorHex);
                currentIndex = foundIdx >= 0 ? foundIdx : 0;
                layer.style.backgroundColor = colorHex;
                updateHud(colors[currentIndex].name);
                colorsViewed.add(currentIndex);
            } else {
                currentIndex = index || 0;
                layer.style.backgroundColor = colors[currentIndex].hex;
                updateHud(colors[currentIndex].name);
                colorsViewed.add(currentIndex);
            }
            layer.style.display = 'block';
            if (document.documentElement.requestFullscreen) {
                document.documentElement.requestFullscreen();
            } else if (document.documentElement.webkitRequestFullscreen) {
                document.documentElement.webkitRequestFullscreen();
            } else if (document.documentElement.msRequestFullscreen) {
                document.documentElement.msRequestFullscreen();
            }
            showHud();
        }
        function nextColor() {
            currentIndex = (currentIndex + 1) % colors.length;
            const c = colors[currentIndex];
            document.getElementById('diagnostic-layer').style.backgroundColor = c.hex;
            updateHud(c.name);
            showHud();
            colorsViewed.add(currentIndex);
        }
        function prevColor() {
            currentIndex = (currentIndex - 1 + colors.length) % colors.length;
            const c = colors[currentIndex];
            document.getElementById('diagnostic-layer').style.backgroundColor = c.hex;
            updateHud(c.name);
            showHud();
            colorsViewed.add(currentIndex);
        }
        function updateHud(name) {
            document.getElementById('color-name').innerText = name;
            // Adjust HUD text color for contrast on black screen
            if (name === 'Black') {
                document.getElementById('test-hud').style.background = 'rgba(255,255,255,0.2)';
            } else {
                document.getElementById('test-hud').style.background = 'rgba(15, 23, 42, 0.85)';
            }
        }
        function showHud() {
            const hud = document.getElementById('test-hud');
            hud.style.opacity = '1';
            clearTimeout(hudTimeout);
            document.body.style.cursor = 'default';
            hudTimeout = setTimeout(() => {
                hud.style.opacity = '0';
                document.body.style.cursor = 'none';
            }, 2500);
        }
        function stopTest() {
            document.getElementById('diagnostic-layer').style.display = 'none';
            document.body.style.cursor = 'default';
            clearInterval(fixerInterval);
            document.getElementById('fixer-overlay').classList.add('hidden');
            if (document.exitFullscreen) {
                document.exitFullscreen();
            } else if (document.webkitExitFullscreen) {
                document.webkitExitFullscreen();
            } else if (document.msExitFullscreen) {
                document.msExitFullscreen();
            }
            // Check for dopamine completion
            if (colorsViewed.size >= 5) { // If they viewed at least the main RGBWB
                triggerCompletion();
            }
        }
        function toggleFixer() {
            const overlay = document.getElementById('fixer-overlay');
            if (fixerInterval) {
                clearInterval(fixerInterval);
                fixerInterval = null;
                overlay.classList.add('hidden');
                document.getElementById('diagnostic-layer').style.backgroundColor = colors[currentIndex].hex;
            } else {
                overlay.classList.remove('hidden');
                let toggle = false;
                fixerInterval = setInterval(() => {
                    const layer = document.getElementById('diagnostic-layer');
                    layer.style.backgroundColor = toggle ? '#ffffff' : colors[currentIndex].hex;
                    toggle = !toggle;
                }, 100); // 10Hz strobe
            }
        }
        // --- Dopamine / Completion Logic ---
        function triggerCompletion() {
            const modal = document.getElementById('completion-modal');
            modal.classList.remove('hidden');
            modal.classList.add('flex');
            createConfetti();
        }
        function closeModal() {
            const modal = document.getElementById('completion-modal');
            modal.classList.add('hidden');
            modal.classList.remove('flex');
            colorsViewed.clear();
        }
        function createConfetti() {
            const colors = ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#00ffff'];
            for (let i = 0; i < 50; i++) {
                const conf = document.createElement('div');
                conf.classList.add('confetti');
                conf.style.left = Math.random() * 100 + 'vw';
                conf.style.top = -10 + 'px';
                conf.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
                conf.style.animationDuration = (Math.random() * 2 + 2) + 's';
                document.body.appendChild(conf);
                setTimeout(() => conf.remove(), 4000);
            }
        }
        // --- Tutorial Logic ---
        const tourSteps = [
            {
                element: '#hero-control-panel h3',
                text: "Welcome! This tool will help you find dead pixels on your screen."
            },
            {
                element: '#start-btn',
                text: "Click here to start the automatic full-screen cycle."
            },
            {
                element: '#manual-controls',
                text: "Or check specific colors individually here if you spot something suspicious."
            },
            {
                element: '.sidebar-tool-info',
                text: "Don't forget to wipe your screen first! Dust looks just like a dead pixel."
            }
        ];
        function startTour() {
            let currentStep = 0;
            function showStep(index) {
                // Clear previous highlights
                document.querySelectorAll('.tour-highlight').forEach(el => el.classList.remove('tour-highlight'));
                document.querySelectorAll('.tour-tooltip').forEach(el => el.remove());
                if (index >= tourSteps.length) return;
                const step = tourSteps[index];
                const element = document.querySelector(step.element);
                if (element) {
                    element.classList.add('tour-highlight');
                    const tooltip = document.createElement('div');
                    tooltip.classList.add('tour-tooltip');
                    tooltip.innerText = step.text;
                    // Position tooltip
                    const rect = element.getBoundingClientRect();
                    tooltip.style.top = (window.scrollY + rect.bottom + 15) + 'px';
                    tooltip.style.left = (rect.left + (rect.width / 2) - 125) + 'px'; // Center roughly
                    // Add Next Button
                    const btn = document.createElement('button');
                    btn.innerText = index === tourSteps.length - 1 ? "Finish" : "Next";
                    btn.style.marginTop = "0.5rem";
                    btn.style.padding = "4px 8px";
                    btn.style.background = "#3b82f6";
                    btn.style.color = "white";
                    btn.style.borderRadius = "4px";
                    btn.style.fontSize = "0.75rem";
                    btn.onclick = (e) => {
                        e.stopPropagation();
                        showStep(index + 1);
                    };
                    tooltip.appendChild(btn);
                    document.body.appendChild(tooltip);
                    // Scroll to element
                    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }
            showStep(0);
            // Close tour on click outside
            document.addEventListener('click', function closeTour(e) {
                if (!e.target.closest('.tour-tooltip') && !e.target.closest('#tour-btn')) {
                    document.querySelectorAll('.tour-highlight').forEach(el => el.classList.remove('tour-highlight'));
                    document.querySelectorAll('.tour-tooltip').forEach(el => el.remove());
                    document.removeEventListener('click', closeTour);
                }
            });
        }
        // --- Event Listeners ---
        document.addEventListener('keydown', (e) => {
            if (document.getElementById('diagnostic-layer').style.display === 'block') {
                if (e.key === 'Escape') stopTest();
                if (e.key === 'ArrowRight' || e.key === ' ' || e.key === 'Enter') nextColor();
                if (e.key === 'ArrowLeft') prevColor();
                if (e.key.toLowerCase() === 'f') toggleFixer(); // Secret key for fixer
            }
        });
        document.addEventListener('mousemove', () => {
            if (document.getElementById('diagnostic-layer').style.display === 'block') {
                showHud();
            }
        });
        // Initialize Scroll to Top
